L37_1 = "어떤 일이 터질지 모르는 현장에서 마지막까지 믿을 수 있는 건, 자기 몸 밖에 없거든."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "現場ではいつ何が起こるかわからない。そんな時最後まで頼れるのは自分の体しかないんだ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "In a field filled with uncertainty, the only thing you can trust until the end is your own body."
L36_1.m_Talk_ENG = L37_1
L37_1 = "在不知道會發生什麼事情的火災現場，所有事情都亂了套的時候，唯一可以信任的就是自己的身體。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "在不知道会发生什么事情的火灾现场，所有事情都乱了套的时候，唯一可以信任的就是自己的身体。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "In a field filled with uncertainty, the only thing you can trust until the end is your own body."
L36_1.m_Talk_DEU = L37_1
L37_1 = "In a field filled with uncertainty, the only thing you can trust until the end is your own body."
