L37_1.m_Talk_JPN = L38_1
L38_1 = "Above all, I feel like I'm going beyond my limits a little at a time... It's not bad."
L37_1.m_Talk_ENG = L38_1
L38_1 = "最重要的是，那種一點一點突破自己極限的滋味……很不錯。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "最重要的是，那种一点一点突破自己极限的滋味……很不错。"
