L38_1 = "MEMBER_YAKSHA_NPC_A"
L37_1.m_CharStrID = L38_1
L38_1 = "누님께서 무슨 생각을 하시는지는 모르겠지만, 나는 널 인정할 생각이 없거든."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "姉貴が何を考えてるのかはわからないけど、俺はお前を認めるつもりなんかさらさらないんだ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I don't know what Judy was thinking, but I have no intention of acknowledging you."
